const $=s=>document.querySelector(s);const app=$('#app');let page='welcome',toastTimer;const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',shop:'<circle cx="9" cy="20" r="1.6"/><circle cx="17" cy="20" r="1.6"/><path d="M2 3h2.2l.7 2.8h14.2l-1.5 7.2H7.4L6.2 7.2"/><path d="M7.4 13h9.2"/><path d="M19.2 5.8h2.2"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 9 2 2 5-5M8 16h8"/>',meal:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="5"/>',money:'<rect x="2" y="5" width="20" height="14" rx="3"/><circle cx="12" cy="12" r="3"/>'};const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.home}</svg>`;const casaLogo=`<svg class="casa-logo" viewBox="0 0 100 100" aria-hidden="true"><defs><filter id="sticker" x="-10%" y="-10%" width="120%" height="120%"><feDropShadow dx="0" dy="2" stdDeviation="0" flood-color="#1c2c12" flood-opacity=".35"/></filter></defs><g filter="url(#sticker)"><ellipse cx="50" cy="56" rx="32" ry="36" fill="#243816"/><ellipse cx="50" cy="54" rx="29" ry="33" fill="#2F4A1E"/><ellipse cx="50" cy="54" rx="23" ry="27" fill="#6F9A3C"/><ellipse cx="50" cy="56" rx="17" ry="21" fill="#F6EEB8"/><!-- house pit --><path d="M50 42l14 11v15.5a3.5 3.5 0 0 1-3.5 3.5H39.5a3.5 3.5 0 0 1-3.5-3.5V53Z" fill="#8B5A2B"/><path d="M50 42l14 11H36Z" fill="#A56B38"/><rect x="46" y="56" width="8" height="12" rx="1.5" fill="#F1DD81"/><rect x="40" y="49" width="6" height="6" rx="1" fill="#F6EEB8"/><rect x="54" y="49" width="6" height="6" rx="1" fill="#F6EEB8"/><!-- face on flesh above house --><circle cx="39" cy="48" r="3.2" fill="#243816"/><circle cx="61" cy="48" r="3.2" fill="#243816"/><circle cx="40" cy="47" r="1" fill="#FFF9DC"/><circle cx="62" cy="47" r="1" fill="#FFF9DC"/><path d="M44 61c2.8 3.6 9.2 3.6 12 0" fill="none" stroke="#243816" stroke-width="2.6" stroke-linecap="round"/><!-- rosy cheeks --><circle cx="36" cy="55" r="2.4" fill="#E8A87C" opacity=".55"/><circle cx="64" cy="55" r="2.4" fill="#E8A87C" opacity=".55"/><!-- leaf hat --><path d="M63 20c10 3 14 13 11 22-8-3-13-10-11-22Z" fill="#86AF37"/><path d="M63 20c1 9 5 16 11 22" fill="none" stroke="#2F4A1E" stroke-width="1.6"/></g></svg>`;
const avocado='<svg viewBox="0 0 40 50" aria-hidden="true"><path d="M20 2C12 2 12 12 7 21-5 43 10 50 20 48 32 50 46 38 32 20 27 13 28 2 20 2" fill="#667c48"/><path d="M20 7c-5 0-5 9-10 18-8 15 1 19 10 19s18-5 10-19c-5-9-5-18-10-18" fill="#d2d982"/><circle cx="20" cy="32" r="9" fill="#93664a"/></svg>';
const mealArt=`<svg viewBox="0 0 460 240" role="img" aria-label="איור מקומי דקורטיבי של סלט ופסטה"><rect width="460" height="240" fill="#d8dda5"/><path d="M0 175 460 100v140H0" fill="#c8d08d"/><ellipse cx="237" cy="135" rx="133" ry="83" fill="#b8c2a5" opacity=".3"/><ellipse cx="230" cy="121" rx="133" ry="83" fill="#fcfaf0"/><ellipse cx="230" cy="121" rx="105" ry="61" fill="#e7d4a8"/><g fill="none" stroke="#dbb966" stroke-width="9" stroke-linecap="round"><path d="m165 91 33 20m23-31 26 27m25-17 25 25m-115 11 29 26m26-30 29 26m-52 13 32 15m20-37 27 16m-99-33 28-9"/></g><g fill="#6d8b4f"><ellipse cx="166" cy="119" rx="17" ry="8" transform="rotate(-30 166 119)"/><ellipse cx="266" cy="86" rx="17" ry="8" transform="rotate(30 266 86)"/><ellipse cx="246" cy="151" rx="18" ry="8" transform="rotate(-20 246 151)"/><ellipse cx="201" cy="81" rx="17" ry="8"/></g><g fill="#b66d4c"><circle cx="194" cy="141" r="9"/><circle cx="280" cy="128" r="9"/><circle cx="221" cy="97" r="8"/></g><path d="m373 44-32 146m20-153-10 47m-1-49-10 48m-1-50-10 48" fill="none" stroke="#77866a" stroke-width="5" stroke-linecap="round"/><path d="M74 37c-19 35-21 51-7 58l-16 78" fill="none" stroke="#77866a" stroke-width="6" stroke-linecap="round"/></svg>`;
const roomArt=`<svg viewBox="0 0 400 450" role="img" aria-label="איור מקומי דקורטיבי של בית חם"><path d="M72 183V94a128 128 0 0 1 256 0v89" fill="#f6f3e7"/><path d="M200 33v150M75 112h250" stroke="#d5dba6" stroke-width="7"/><path d="M50 338h302" stroke="#bdc7a8" stroke-width="3"/><ellipse cx="198" cy="365" rx="153" ry="35" fill="#d5dba6"/><rect x="78" y="251" width="239" height="86" rx="22" fill="#81954d"/><rect x="91" y="207" width="212" height="93" rx="25" fill="#91a357"/><rect x="66" y="262" width="32" height="72" rx="13" fill="#6d843d"/><rect x="292" y="262" width="32" height="72" rx="13" fill="#6d843d"/><path d="M101 334v17m184-17v17" stroke="#725e46" stroke-width="8"/><rect x="112" y="229" width="62" height="55" rx="10" fill="#eeead6" transform="rotate(-8 140 250)"/><rect x="215" y="231" width="55" height="49" rx="10" fill="#d3da92" transform="rotate(7 240 250)"/><ellipse cx="194" cy="337" rx="59" ry="18" fill="#af8968"/><path d="M152 343v35m83-35v35" stroke="#8f6b4e" stroke-width="6"/><path d="M340 253v-80" stroke="#6e8257" stroke-width="4"/><g fill="#7a925f"><ellipse cx="325" cy="199" rx="11" ry="27" transform="rotate(-35 325 199)"/><ellipse cx="353" cy="177" rx="10" ry="28" transform="rotate(30 353 177)"/><ellipse cx="350" cy="225" rx="10" ry="25" transform="rotate(40 350 225)"/></g><path d="m321 252 7 51h26l7-51" fill="#ab8160"/><circle cx="195" cy="320" r="9" fill="#f5f1df"/></svg>`;
const initial={shopping:[{id:1,name:'עגבניות שרי',category:'ירקות ופירות',done:false},{id:2,name:'חלב שיבולת שועל',category:'מקרר',done:false},{id:3,name:'לחם מחמצת',category:'מאפים',done:true},{id:4,name:'אבוקדו',category:'ירקות ופירות',qty:2,done:false},{id:5,name:'ביצים',category:'מקרר וביצים',done:false},{id:6,name:'קפה',category:'מזווה',done:false}],tasks:[{id:1,title:'להשקות את העציצים',who:'רועי',when:'היום',done:false},{id:2,title:'להפעיל מכונת כביסה',who:'מאיה',when:'היום',done:false},{id:3,title:'לבחור ארוחה לערב',who:'ביחד',when:'בלי לחץ',done:false}]};let data;try{data=JSON.parse(localStorage.getItem('couple-demo-v1'))||structuredClone(initial)}catch{data=structuredClone(initial)};const save=()=>{try{localStorage.setItem('couple-demo-v1',JSON.stringify(data));return true}catch{toast('האחסון המקומי מלא. השינוי לא נשמר; נסו להסיר תמונה.');return false}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token=sessionStorage.getItem('demo-invite')||crypto.randomUUID();sessionStorage.setItem('demo-invite',token);let revoked=sessionStorage.getItem('demo-revoked')==='true',accepted=sessionStorage.getItem('demo-accepted')==='true';const inviteUrl=()=>{const url=new URL('./',location.href);url.searchParams.set('invite',token);return url.href};const qrData=()=>`data:image/svg+xml;charset=utf-8,${encodeURIComponent(LocalQR.toSVG(inviteUrl()))}`;
function toast(text){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),3500)}
function appHeader(){return `<header class="top"><div class="side left">${avatar('roei')}<button class="gear" data-go="settings" aria-label="הגדרות">${gearIcon}</button></div><button class="brand centerbrand" data-go="home">${casaLogo}<span class="brandtext"><span class="brandname">CASA</span><span class="greeting">שלום ${esc(data.profiles.roei.name)}</span></span></button><div class="side right" aria-hidden="true"></div></header>`}

function nav(){return `<nav class="nav" aria-label="ניווט ראשי">${[['home','home','היום'],['shopping','shop','קניות'],['meals','meal','תפריט'],['expenses','money','כסף']].map(([p,i,t])=>`<button data-go="${p}" class="${page===p||(p==='meals'&&(page==='meal'||page==='meal-edit'))?'active':''}">${icon(i)}${t}</button>`).join('')}</nav>`}

function taskRows(list=data.tasks){return list.length?list.map(t=>`<div class="task" data-task-row="${t.id}"><button class="check ${t.done?'done':''}" data-task="${t.id}" aria-label="${t.done?'ביטול השלמה: ':'השלמה: '}${esc(t.title)}" aria-pressed="${t.done}">${t.done?'✓':''}</button><div class="tasktext ${t.done?'completed':''}">${esc(t.title)}<small>${esc(t.when)} · ${t.done?'הושלמה':'פתוחה'}</small></div><div class="task-avatars" aria-label="אחראים">${t.who==='ביחד'?avatar('roei')+avatar('maya'):avatar(t.who==='מאיה'?'maya':'roei')}</div></div>`).join(''):'<p class="empty">אין מטלות בתצוגה הזו. אפשר לבחור סינון אחר.</p>'}
function shopRows(items){return items.map(t=>`<div class="shop-row ${t.done?'is-bought':''}" data-product="${t.id}"><button class="check purchasecheck ${t.done?'done':''}" data-shop="${t.id}" aria-label="${t.done?'החזרת ':'סימון נקנה: '}${esc(t.name)}" aria-pressed="${t.done}">${t.done?'✓':''}</button><span class="productart" aria-hidden="true">${productArt(t.art)}</span><div class="tasktext ${t.done?'completed':''}"><span class="productname">${esc(t.name)}</span><small>${esc(t.unit)}${t.fromMeal?' · מהתפריט':''}</small></div>${!t.done?`<div class="quantity" aria-label="כמות ${esc(t.name)}"><button data-qty="${t.id}" data-step="-1" aria-label="הפחתת כמות ${esc(t.name)}" ${t.qty<=1?'disabled':''}>−</button><output aria-label="כמות ${esc(t.name)}">${t.qty}</output><button data-qty="${t.id}" data-step="1" aria-label="הגדלת כמות ${esc(t.name)}" ${t.qty>=99?'disabled':''}>+</button></div><button class="edit-category" data-edit-category="${t.id}" aria-label="שינוי קטגוריה ${esc(t.name)}"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="m4 12 9-9 4 4-9 9-5 1Z M11 5l4 4"/></svg></button>`:`<span class="boughtquantity">${t.qty} ${esc(t.unit)}</span>`}${editingCategory===t.id&&!t.done?`<label class="categoryeditor">קטגוריה <select data-item-category="${t.id}" aria-label="קטגוריה ${esc(t.name)}">${allShoppingCategories().map(c=>`<option ${t.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:''}</div>`).join('')}
function quick(){return `<div class="quick"><input id="quick-item" aria-label="מה חסר בבית?" placeholder="מה חסר בבית?" maxlength="90"><button id="add-item" aria-label="הוספה לקניות">+</button></div>`}
function head(title,sub,action=''){return `<div class="head"><div><div class="eyebrow">CASA · ${esc(data.houseName||'הבית של רועי ומאיה')} · נתוני דוגמה</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function welcome(){return `<div class="welcome"><div><div class="eyebrow">פחות לתאם. יותר להיות יחד.</div><h1>כל מה שצריך,<br>כדי להרגיש בבית.</h1><p>הקניות, הדברים הקטנים ומה נאכל הערב. מקום נעים אחד, לשניכם.</p><button class="primary" data-go="login">בואו נתחיל</button><button class="secondary" data-go="home">להציץ בהדגמה</button><div class="features"><span>קניות ביחד</span><span>מה עושים היום</span><span>האוכל שלנו</span></div><div class="footnote">CASA — שם המוצר. הדגמה מקומית בלבד.</div></div><div class="heroscene">${roomArt}</div></div>`}
function login(){return `<div class="center"><button class="back" data-go="welcome">→ בחזרה</button><div class="card"><div class="onboardingstep">מתחילים במקום קטן ומשותף</div><h1>היי, טוב שבאתם.</h1><p>בהמשך, לכל אחד יהיה חשבון אישי. כרגע אפשר להכיר את הבית בלי להירשם ובלי למסור פרטים.</p><button class="secondary nohover" disabled>כניסה באימייל — בחיבור החשבונות בהמשך</button><button class="primary" data-go="create">כניסה להדגמה</button><div class="notice">אין כאן כניסה אמיתית, סיסמאות או חשבון ענן. הנתונים נשמרים רק בדפדפן הזה.</div></div></div>`}
function create(){return `<div class="center"><button class="back" data-go="login">→ בחזרה</button><div class="card"><div class="onboardingstep">01 / הבית המשותף · הדגמה</div><h1>מקום קטן לשניכם.</h1><p>נתחיל עם בית לדוגמה, ונראה איך מצרפים את האדם השני.</p><label for="house-name">איך נקרא לבית?</label><input id="house-name" value="${esc(data.houseName||'הבית של רועי ומאיה')}" maxlength="60" style="margin-top:8px"><button class="primary" id="create-home">יצירת בית להדגמה</button><div class="footnote">השם יישמר מקומית בלבד. לא נוצר חשבון או בית בשרת.</div></div></div>`}
function invite(){return `<div class="center"><button class="back" data-go="settings">→ בחזרה להגדרות</button><div class="card"><div class="onboardingstep">02 / מצטרפים יחד · הדגמה</div><h1>שני טלפונים.<br>בית אחד.</h1><p>כשאתם יחד, הכי פשוט לסרוק במצלמה הרגילה של הטלפון. מרחוק אפשר לשתף קישור.</p>${revoked?'<div class="notice">קישור ההדגמה בוטל בדפדפן הזה.</div><button class="primary" id="renew">יצירת QR הדגמה חדש</button>':`<img class="qr" src="${qrData()}" alt="QR אמיתי של קישור הזמנה מקומי להדגמה"><div class="notice">הדגמה מקומית — עדיין לא מחבר בין טלפונים. ה־QR פותח את אותה הדגמה בלבד, בלי לצרף חשבון או לסנכרן מידע. אין בו פרטי חשבון.</div><div class="link">${esc(inviteUrl())}</div><button class="primary" id="copy-invite">העתקת קישור לשיתוף</button><button class="secondary" data-go="accept">תצוגת קבלת ההזמנה</button><button class="quiet" id="revoke" style="margin-top:18px">ביטול ההזמנה בהדגמה</button>`}<div class="footnote">במוצר האמיתי: כניסה אישית ואישור מפורש, קישור חד־פעמי שפג לאחר 24 שעות וניתן לביטול. האבטחה הזו עדיין לא מחוברת לשרת.</div></div></div>`}
function accept(){return `<div class="center"><button class="back" data-go="invite">→ בחזרה להזמנה</button><div class="card"><div class="onboardingstep">תצוגה בלבד · אין התחברות בין מכשירים</div><h1>${accepted?'השלב הבא יהיה ביחד.':'הזמנה לבית לדוגמה'}</h1><p>${accepted?'אישור ההדגמה נרשם בדפדפן הזה בלבד. לא צורף אדם לבית אמיתי.':'במוצר המלא, כאן נכנסים לחשבון אישי, בודקים לאיזה בית הוזמנתם ומאשרים הצטרפות.'}</p><div class="notice">${revoked?'ההזמנה בוטלה בהדגמה.':accepted?'ההזמנה סומנה כנוצלה בהדגמה המקומית.':'הבית של רועי ומאיה · נתוני דוגמה בלבד'}</div>${!accepted&&!revoked?'<button class="primary" id="accept-demo">הדמיית אישור הצטרפות</button>':''}<button class="secondary" data-go="home">פתיחת הבית לדוגמה</button></div></div>`}
function home(){const dinner=getMenu().find(m=>m.category==='dinner')||getMenu()[0];const todayItems=eventsOn(selectedDay);return `<div class="grid homegrid"><div class="stack"><section class="card calendarcard"><div class="cardhead"><h2>היומן של הבית</h2><button type="button" class="quiet" id="toggle-month-view" aria-pressed="${monthView}">${monthView?'שבועיים':'חודש מלא'}</button></div>${calendarWidget()}<div class="daypanel"><div class="cardhead"><h3>${formatDayLabel(selectedDay)}</h3><span class="sub">${todayItems.length?todayItems.length+' פריטים':'יום פתוח'}</span></div>${todayItems.length?todayItems.map(e=>`<div class="dayitem"><span class="dot ${e.kind}"></span><div><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small></div></div>`).join(''):'<p class="sub">אין אירועים ביום הזה. אפשר להוסיף בהמשך מהתפריט או מרעיונות לזמן יחד.</p>'}</div></section><section class="card upcomingcard"><div class="cardhead"><h2>לקראת השבוע</h2><button class="quiet" data-go="dates">רעיונות</button></div><div class="upcoming"><div class="dateblock">יום<strong>ו׳</strong></div><div><h3>ערב קטן לשנינו</h3><p class="sub">בבית או בחוץ — עוד נבחר</p></div></div></section></div><div class="stack"><section class="card mealcard"><div class="cardhead"><h2>מה אוכלים הערב?</h2><button class="quiet" data-go="meals">התפריט</button></div><div class="mealart">${foodArt(dinner)}</div><div class="mealinfo"><div><h3>${esc(dinner.title)}</h3><p>${dinner.time} דקות · מהמנות שאוהבים · דוגמה</p></div><button class="secondary" data-meal="${dinner.id}">למנה</button></div></section><section class="card quickcard"><div class="cardhead"><h2>חסר משהו?</h2><button class="quiet" data-go="shopping">הרשימה</button></div>${quick()}<div class="sub">${data.shopping.filter(t=>!t.done).length} פריטים מחכים בקניות לדוגמה</div></section></div></div>`}

function shopping(){const open=data.shopping.filter(t=>!t.done),bought=data.shopping.filter(t=>t.done),categories=allShoppingCategories().filter(c=>open.some(t=>t.category===c));if(shopFilter!=='all'&&!categories.includes(shopFilter))shopFilter='all';const progress=data.shopping.length?Math.round(bought.length/data.shopping.length*100):0;const suggestions=shoppingSuggestions();const planned=getPlannedDishes();return `${head('מה חסר בבית?','רשימה חכמה יותר, עדיין פשוטה בסופר.')}<div class="shoppinglayout"><div class="shoppingmain"><section class="card shopcomposer"><div class="cardhead"><h2>מוסיפים לרשימה</h2><span class="sub">הדגמה מקומית</span></div><div class="quick"><input id="quick-item" aria-label="מה חסר בבית?" placeholder="למשל חלב, אבוקדו או סבון…" maxlength="90" autocomplete="off"><button id="add-item" aria-label="הוספה לקניות">+</button></div><div class="addoptions"><label>כמות <input id="add-qty" aria-label="כמות להוספה" type="number" min="1" max="99" step="1" value="1" inputmode="numeric"></label><label>יחידה <select id="add-unit" aria-label="יחידה להוספה"><option>יח׳</option><option>חבילות</option><option>בקבוקים</option></select></label></div><p id="add-error" role="alert"></p><p id="classification-hint" class="sub">סיווג לפי מילון עברית מקומי, בלי AI. תמיד אפשר לשנות קטגוריה.</p><div class="quickproducts" aria-label="הצעות מהירות">${suggestions.map(n=>`<button data-common="${esc(n)}">+ ${esc(n)}</button>`).join('')}</div>${planned.length?`<div class="plannedbox"><div class="cardhead"><h3>מהתפריט המתוכנן</h3><span class="sub">${planned.length} מנות</span></div>${planned.map(m=>`<button class="secondary planned-btn" data-add-dish="${m.id}">+ רכיבי ${esc(m.title)}</button>`).join('')}</div>`:''}</section><div class="shoppingfilters" aria-label="סינון קטגוריות"><button data-shop-filter="all" aria-pressed="${shopFilter==='all'}" class="${shopFilter==='all'?'selected':''}">הכול</button>${categories.map(c=>`<button data-shop-filter="${esc(c)}" aria-pressed="${shopFilter===c}" class="${shopFilter===c?'selected':''}">${esc(c)}</button>`).join('')}</div><div class="categorygroups">${open.length?categories.filter(c=>shopFilter==='all'||shopFilter===c).map(c=>`<section class="card grocerygroup"><div class="cardhead"><h2>${esc(c)}</h2><span class="sub">${open.filter(t=>t.category===c).length} פריטים</span></div>${shopRows(open.filter(t=>t.category===c))}</section>`).join(''):'<section class="card"><h2>הכול כבר בסל.</h2><p>אפשר להוסיף עוד משהו, או להחזיר פריט מהרשימה שנקנתה.</p></section>'}</div><section class="card boughtsection"><button class="boughtheader" id="toggle-bought" aria-expanded="${boughtExpanded}"><span>כבר בסל <span class="sub">(${bought.length})</span></span><span aria-hidden="true">${boughtExpanded?'−':'+'}</span></button>${boughtExpanded?(bought.length?shopRows(bought)+`<button class="secondary" id="clear-bought" style="margin-top:14px">ניקוי הפריטים שנקנו</button>`:'<p class="sub" style="margin-top:14px">עדיין לא סומן פריט כנקנה.</p>'):'<p class="sub">הפריטים נשמרים כאן. אפשר לפתוח ולהחזיר לרשימה.</p>'}</section></div><aside class="card shoppingprogress"><span class="eyebrow">בסיבוב הזה</span><h2>עוד ${open.length} פריטים לקנייה</h2><p>${bought.length} מתוך ${data.shopping.length} כבר בסל</p><div class="progressbar" role="progressbar" aria-label="פריטים שנקנו" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div><div class="notice">נתוני דוגמה · השינויים נשמרים רק בדפדפן הזה. עדיין אין סנכרון בין טלפונים.</div></aside></div>`}

function tasks(){const filtered=data.tasks.filter(t=>(taskStatus==='all'||(taskStatus==='done'?t.done:!t.done))&&(taskOwner==='all'||t.who===taskOwner));return `${head('מטלות הבית','כל הדברים הקטנים, במקום אחד.')}<section class="card taskpage"><div class="cardhead"><h2>בקצב של הבית</h2><span class="sub">${data.tasks.filter(t=>!t.done).length} פתוחות</span></div><div class="filtertabs" aria-label="סינון מצב">${[['all','הכול'],['open','פתוחות'],['done','הושלמו']].map(([v,l])=>`<button data-status="${v}" aria-pressed="${taskStatus===v}" class="${taskStatus===v?'selected':''}">${l}</button>`).join('')}</div><label class="selectlabel">לפי אחראי <select id="task-owner"><option value="all" ${taskOwner==='all'?'selected':''}>כולם</option><option value="רועי" ${taskOwner==='רועי'?'selected':''}>${esc(data.profiles.roei.name)}</option><option value="מאיה" ${taskOwner==='מאיה'?'selected':''}>${esc(data.profiles.maya.name)}</option><option value="ביחד" ${taskOwner==='ביחד'?'selected':''}>ביחד</option></select></label><div id="task-list">${taskRows(filtered)}</div><div class="addtask"><h3>עוד משהו קטן?</h3><input id="task-title" aria-label="שם מטלה חדשה" placeholder="מה צריך לעשות?" maxlength="100"><div class="taskfields"><label>מי מטפל?<select id="new-task-owner"><option value="רועי">${esc(data.profiles.roei.name)}</option><option value="מאיה">${esc(data.profiles.maya.name)}</option><option value="ביחד">ביחד</option></select></label><label>מתי?<select id="new-task-when"><option>היום</option><option>מחר</option><option>השבוע</option><option>בלי לחץ</option></select></label><button class="primary" id="add-task">הוספת מטלה</button></div></div><div class="notice">השלמה והוספה נשמרות מקומית בלבד. ״היום״ ו״מחר״ הם תוויות הדגמה — אין מנוע תאריכים, חזרות או התראות.</div></section>`}
function meals(){ensureMenu();const groups=menuCategories.map(c=>({...c,items:getMenu().filter(m=>m.category===c.id)}));return `${head('התפריט של CASA','האוכל של הבית, מסודר כמו במסעדה קטנה.')}<div class="menubook"><div class="menubook-top"><span>תפריט הבית</span><span>CASA</span></div>${groups.map(g=>`<section class="menusection" id="menu-${g.id}"><div class="menusection-head"><h2>${g.label}</h2><span class="ornament">✦</span></div>${g.items.length?g.items.map(m=>`<article class="menudish"><button class="menudish-main" data-meal="${m.id}" aria-label="פרטי ${esc(m.title)}"><div class="menudish-visual" aria-hidden="true">${foodArt(m)}</div><div class="menudish-row"><span class="menudish-name">${esc(m.title)}</span><span class="leaders" aria-hidden="true"></span><span class="menudish-time">${m.time}'</span></div><p class="menudish-note">${esc(m.note||m.instructions||'')}</p><p class="menudish-ings"><span>רכיבים</span> ${m.ingredients.map(esc).join(' · ')}</p></button><div class="menudish-actions"><button class="quiet" data-edit-meal="${m.id}">עריכה</button><button class="quiet" data-plan-meal="${m.id}">לתכנון השבוע</button></div></article>`).join(''):'<p class="sub">עדיין אין מנות בקטגוריה הזו.</p>'}</section>`).join('')}<div class="menu-add card"><h3>מנה חדשה לתפריט</h3><p class="sub">נשמרת רק במכשיר הזה. לא מאגר ציבורי.</p><button class="primary" data-go="meal-edit">הוספת מנה</button></div></div><div class="notice">תפריט פרטי לדוגמה. האיורים דקורטיביים מקומיים.</div>`}

function meal(){const m=getMenu().find(m=>m.id===selectedMeal)||getMenu()[0];return `<button class="back" data-go="meals">→ בחזרה לתפריט</button>${head(m.title,`${m.time} דקות · רכיבים ומצרכים לקניות`)}<div class="grid"><section class="card"><div class="mealart" style="height:220px">${foodArt(m)}</div><h2>בקצרה</h2><p style="margin-top:10px">${esc(m.instructions||m.note||'')}</p><h3 style="margin-top:18px">רכיבים</h3><ul class="inglist">${m.ingredients.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><button class="secondary" data-edit-meal="${m.id}" style="margin-top:16px">עריכת המנה</button></section><section class="card"><h2>מה חסר לנו?</h2><p style="margin-top:8px">בחרו רק מה שצריך לקנות.</p>${m.ingredients.map(n=>`<label class="task"><input type="checkbox" name="ingredient" value="${esc(n)}" style="width:21px;height:21px;accent-color:var(--green)"><span>${n}</span></label>`).join('')}<button class="primary" id="ingredients" style="margin-top:20px">הוספת הנבחרים לקניות</button><button class="secondary" id="add-all-ingredients" style="margin-top:10px">הוספת כל הרכיבים</button><div class="footnote">פריטים שכבר ברשימה הפתוחה ימוזגו לכמות במקום כפילות.</div></section></div>`}

function expenses(){return `${head('כסף, בצורה פשוטה.','תמונת מצב משותפת — כל הסכומים כאן דמיוניים.')}<div class="grid"><section class="card"><span class="sub">יתרת דוגמה בלבד</span><div class="expense" dir="ltr">120 CZK</div><h3>מאיה לרועי · בתרחיש הדוגמה</h3><div class="notice">מטבע הדגמה: CZK. המטבע והחלוקה שלכם עדיין לא אושרו. אין כאן חישוב פיננסי פעיל או העברת כסף.</div></section><section class="card"><h2>הוצאות לדוגמה</h2><div class="minirow"><div>קניות לבית<p class="sub">רועי שילם · חלוקה 50/50</p></div><strong dir="ltr">600 CZK</strong></div><div class="minirow"><div>ארוחה ביחד<p class="sub">מאיה שילמה · חלוקה 50/50</p></div><strong dir="ltr">360 CZK</strong></div><p class="footnote">הוספה, עריכת הוצאות והתחשבנויות ייבנו אחרי אישור כללי הכסף.</p></section></div>`}
function dates(){return `${head('זמן קטן לשנינו','רעיונות לדוגמה, בלי לקבוע או לשלוח דבר.')}<div class="grid"><section class="card"><div class="heroscene" style="height:230px;border-radius:16px">${roomArt}</div><h2 style="margin-top:16px">ערב בלי מסכים</h2><p>משהו טעים, מוזיקה ושיחה על הספה.</p><div class="notice">בבית · עלות לפי מה שכבר יש · רעיון לדוגמה</div><button class="secondary" id="favorite-date">${data.favorite?'♥ נשמר במועדפים המקומיים':'שמירה במועדפים להדגמה'}</button></section><section class="card"><h2>הרעיונות שלכם, בקצב שלכם</h2><p style="margin-top:14px">בהמשך: תמונה, עלות משוערת, כבר עשינו והפיכה לאירוע. אין כאן יצירת אירוע אמיתי או הזמנה ביומן.</p></section></div>`}
function render(){ensureV2();ensureShopping();const views={welcome,login,create,invite,accept,home,shopping,meals,meal,'meal-edit':mealEdit,expenses,dates,settings};app.innerHTML=`<main class="shell">${appHeader()}<div class="demo">הדגמה מקומית · כל התוכן נתוני דוגמה · ללא חשבונות או סנכרון ענן</div>${(views[page]||welcome)()}${!['welcome','login','create','invite','accept','settings','meal-edit'].includes(page)?'<div class="sectionlinks"><button data-go="dates">רעיונות לזמן יחד</button><button data-go="meals">התפריט</button></div><div class="footnote">כל השינויים נשמרים במכשיר הזה בלבד. <button class="quiet" id="reset">איפוס נתוני הדוגמה</button></div>':''}</main>${!['welcome','login','create','invite','accept','settings','meal-edit'].includes(page)?nav():''}`;bind()}
function go(p){if(p==='tasks')p='home';page=p;render();window.scrollTo(0,0)}
function addItem(){const input=$('#quick-item'),name=input.value.trim().replace(/\s+/g,' ');const error=$('#add-error');const fail=msg=>{if(error)error.textContent=msg;else toast(msg)};if(!name){fail('מה נוסיף? כתבו שם מוצר.');input.focus();return}const value=$('#add-qty')?.value??'1';const qty=Number(value);if(!value.trim()||!Number.isInteger(qty)||qty<1||qty>99){fail('בחרו כמות שלמה בין 1 ל־99.');return}const unit=$('#add-unit')?.value||'יח׳';const existing=data.shopping.find(t=>!t.done&&productKey(t.name)===productKey(name)&&t.unit===unit);if(existing&&existing.qty+qty>99){fail('הכמות הכוללת גדולה מ־99. אפשר לעדכן את הכמות ברשימה.');return}if(existing){existing.qty+=qty}else{const info=lookupProduct(name);data.shopping.push({id:Date.now(),name,qty,unit,category:info.category,art:info.art,shoppingV3:true,done:false})}shopFilter='all';save();render();$('#quick-item')?.focus();bumpFreq(existing?existing.name:name);toast(existing?'הפריט כבר ברשימה — הכמות עודכנה':'נוסף לרשימה המקומית')}
function bind(){bindV2();bindShopping();bindCasa();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>toggleShopping(+b.dataset.shop));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{let t=data.tasks.find(t=>t.id===+b.dataset.task);t.done=!t.done;save();render()});if($('#add-item')){$('#add-item').onclick=addItem;$('#quick-item').onkeydown=e=>{if(e.key==='Enter')addItem()}}if($('#create-home'))$('#create-home').onclick=()=>{data.houseName=$('#house-name').value.trim()||'הבית שלנו';save();go('invite')};if($('#copy-invite'))$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(inviteUrl());toast('הקישור להדגמה הועתק. לא נשלחה הזמנה.')}catch{toast('ההעתקה לא זמינה כאן. אפשר להעתיק מהקישור המוצג.')}};if($('#revoke'))$('#revoke').onclick=()=>{revoked=true;sessionStorage.setItem('demo-revoked','true');render()};if($('#renew'))$('#renew').onclick=()=>{token=crypto.randomUUID();sessionStorage.setItem('demo-invite',token);revoked=false;accepted=false;sessionStorage.removeItem('demo-revoked');sessionStorage.removeItem('demo-accepted');render()};if($('#accept-demo'))$('#accept-demo').onclick=()=>{accepted=true;sessionStorage.setItem('demo-accepted','true');render()};if($('#reset'))$('#reset').onclick=()=>{data=structuredClone(initial);save();render();toast('נתוני הדוגמה אופסו')};if($('#favorite-date'))$('#favorite-date').onclick=()=>{data.favorite=!data.favorite;save();render()};if($('#ingredients'))$('#ingredients').onclick=()=>{const chosen=[...document.querySelectorAll('[name="ingredient"]:checked')].map(e=>e.value);if(!chosen.length){toast('בחרו לפחות מצרך אחד שחסר');return}const count=addIngredientNames(chosen);go('shopping');toast(count?`${count} מצרכים עודכנו ברשימה המקומית`:'המצרכים כבר ברשימה הפתוחה')}}

const gearIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m9 3 1-1h4l1 3 3 1 3 3-2 3 1 3-3 3-3-1-2 3-4-1-1-3-3-1-1-4 2-2V6l3-2Z"/><circle cx="12" cy="11" r="3"/></svg>';
function ensureV2(){if(!data.profiles)data.profiles={roei:{name:'רועי',photo:null},maya:{name:'מאיה',photo:null}};
if(!data.v2Tasks){data.tasks.push({id:1004,title:'לסדר את המדף בכניסה',who:'ביחד',when:'השבוע',done:false},{id:1005,title:'לקפל את המצעים',who:'מאיה',when:'אתמול',done:true});data.v2Tasks=true;save()}}
ensureV2();
let menuCategory='breakfast',selectedMeal='pasta',taskStatus='all',taskOwner='all';
const menuCategories=[{id:'breakfast',label:'ארוחות בוקר'},{id:'lunch',label:'צהריים'},{id:'snack',label:'ביניים'},{id:'dinner',label:'ערב'}];

function avatar(key){const p=data.profiles[key];return p.photo?`<img class="avatar profilephoto" src="${p.photo}" alt="${esc(p.name)} — תמונת פרופיל מקומית" title="${esc(p.name)}">`:`<span class="avatar initials" role="img" aria-label="${esc(p.name)} — ראשי תיבות" title="${esc(p.name)}">${esc(p.name.charAt(0))}</span>`}
function foodArt(m){if(m.art==='pasta')return mealArt;const center=m.art==='toast'?'<rect x="133" y="60" width="190" height="125" rx="28" fill="#a87b45"/><rect x="143" y="70" width="170" height="105" rx="22" fill="#d8ba78"/><path d="m163 143 35-52 18 65 22-63 17 60 24-57" stroke="#8d9e39" stroke-width="17" stroke-linecap="round" fill="none"/><ellipse cx="255" cy="113" rx="43" ry="32" fill="#faf4db"/><circle cx="255" cy="113" r="18" fill="#d7a634"/>':m.art==='fruit'?'<circle cx="174" cy="121" r="35" fill="#a4ad42"/><circle cx="234" cy="136" r="32" fill="#c29149"/><path d="m169 84 10-16" stroke="#5a7035" stroke-width="7"/><g fill="#748650"><circle cx="285" cy="103" r="15"/><circle cx="305" cy="121" r="15"/><circle cx="281" cy="135" r="15"/><circle cx="298" cy="151" r="14"/></g>':'<ellipse cx="230" cy="125" rx="100" ry="57" fill="#ece3bf"/><g fill="#9baa4e"><ellipse cx="180" cy="110" rx="25" ry="15"/><ellipse cx="266" cy="138" rx="27" ry="16"/><ellipse cx="239" cy="99" rx="24" ry="13"/></g><g fill="#bc854b"><circle cx="218" cy="134" r="14"/><circle cx="277" cy="104" r="13"/></g><g fill="#f9f4dc"><circle cx="198" cy="138" r="7"/><circle cx="242" cy="122" r="9"/><circle cx="258" cy="158" r="7"/></g>';return `<svg viewBox="0 0 460 240" role="img" aria-label="איור דקורטיבי מקומי: ${m.title}"><rect width="460" height="240" fill="#d8dda5"/><path d="M0 190 460 110v130H0" fill="#c8d08d"/><ellipse cx="236" cy="141" rx="140" ry="80" fill="#a3ad67" opacity=".24"/><ellipse cx="230" cy="121" rx="137" ry="85" fill="#fffaf0"/>${center}</svg>`}
function settings(){return `${head('קצת עלינו','העדפות אישיות, רק בהדגמה המקומית.')}<div class="grid"><section class="card"><div class="cardhead"><h2>הפרופיל שלי</h2>${avatar('roei')}</div><label for="profile-name">איך לפנות אליך?</label><input id="profile-name" maxlength="35" value="${esc(data.profiles.roei.name)}"><button class="primary" id="save-profile">שמירת שם מקומית</button><div class="profileedit"><label for="profile-photo">תמונה אישית מהמכשיר</label><label class="secondary uploadlabel" for="profile-photo">בחירת תמונה מהמכשיר<input class="uploadinput" type="file" id="profile-photo" aria-label="בחירת תמונה אישית מהמכשיר" accept="image/jpeg,image/png,image/webp"></label><p class="sub">JPEG, PNG או WebP, עד 8 MB. התמונה תוקטן ותישמר רק בדפדפן.</p><p id="photo-error" role="alert"></p><button class="secondary" id="remove-photo" ${data.profiles.roei.photo?'':'disabled'}>הסרת תמונה</button></div><div class="notice">אין העלאה לשרת ואין חשבון אמיתי. הראשי תיבות הם ברירת המחדל — לא תמונה של אדם אחר.</div></section><div class="stack"><section class="card"><h2>הבית המשותף</h2><p style="margin-top:10px">כשהאדם השני לידך, QR הוא הדרך הקצרה. אפשר גם להעתיק קישור.</p><button class="primary" data-go="invite" style="margin-top:18px">הזמנה לבית · QR</button><div class="footnote">הדגמה בלבד, עדיין לא מחבר בין טלפונים.</div></section><section class="card"><div class="cardhead"><h2>מי עוד בבית לדוגמה?</h2>${avatar('maya')}</div><p>מאיה מופיעה עם ראשי תיבות. במוצר האמיתי, כל אחד ינהל את הפרופיל שלו.</p><button class="secondary" data-go="home" style="margin-top:16px">בחזרה לבית</button></section></div></div>`}
async function uploadProfile(file){const err=$('#photo-error');if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){err.textContent='בחרו תמונת JPEG, PNG או WebP עד 8 MB.';return}const input=$('#profile-photo');input.disabled=true;try{const image=await createImageBitmap(file);if(!image.width||!image.height)throw Error('invalid');const canvas=document.createElement('canvas');canvas.width=canvas.height=160;const ctx=canvas.getContext('2d');ctx.fillStyle='#f8f4e3';ctx.fillRect(0,0,160,160);const size=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-size)/2,(image.height-size)/2,size,size,0,0,160,160);image.close();const old=data.profiles.roei.photo;data.profiles.roei.photo=canvas.toDataURL('image/jpeg',.78);if(!save()){data.profiles.roei.photo=old;err.textContent='אין מספיק מקום לשמירת התמונה.';input.disabled=false;return}render();toast('התמונה הוקטנה ונשמרה במכשיר בלבד')}catch{err.textContent='לא הצלחנו לקרוא את התמונה. נסו קובץ תמונה תקין אחר.';input.disabled=false}}
function bindV2(){document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{menuCategory=b.dataset.category;render()});document.querySelectorAll('[data-meal]').forEach(b=>b.onclick=()=>{selectedMeal=b.dataset.meal;go('meal')});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{taskStatus=b.dataset.status;render()});if($('#task-owner'))$('#task-owner').onchange=e=>{taskOwner=e.target.value;render()};if($('#add-task'))$('#add-task').onclick=()=>{const title=$('#task-title').value.trim();if(!title){$('#task-title').focus();return}data.tasks.push({id:Date.now(),title,who:$('#new-task-owner').value,when:$('#new-task-when').value,done:false});save();taskStatus='all';taskOwner='all';render();toast('המטלה נוספה מקומית')};if($('#save-profile'))$('#save-profile').onclick=()=>{const name=$('#profile-name').value.trim();if(!name){toast('צריך שם קצר כדי לברך אותך');return}data.profiles.roei.name=name;save();render();toast('השם נשמר מקומית')};if($('#profile-photo'))$('#profile-photo').onchange=e=>uploadProfile(e.target.files[0]);if($('#remove-photo'))$('#remove-photo').onclick=()=>{data.profiles.roei.photo=null;save();render();toast('התמונה הוסרה מהמכשיר')}}

