function normalizeProduct(name){return name.normalize('NFKC').toLowerCase().replace(/[״״"׳']/g,'').replace(/\s+/g,' ').trim()}
function lookupProduct(name){const n=normalizeProduct(name);const exact=productAliases.find(p=>p.aliases.some(a=>normalizeProduct(a)===n));if(exact)return exact;const soft=productAliases.find(p=>p.aliases.some(a=>{const na=normalizeProduct(a);return n.includes(na)||na.includes(n)}));return soft||{category:'כללי',art:'bag',aliases:[name],distinct:true}}
function productKey(name){const p=lookupProduct(name);return normalizeProduct(p.distinct?name:p.aliases[0])}
function allShoppingCategories(){return [...new Set([...groceryCategories,...data.shopping.map(t=>t.category)])]}
function ensureShopping(){let changed=false;for(const t of data.shopping){const info=lookupProduct(t.name);if(!t.shoppingV3){t.qty=Number.isInteger(t.qty)&&t.qty>=1?Math.min(99,t.qty):1;t.unit=t.unit||'יח׳';if(!t.category||['כללי','מהתפריט','מקרר'].includes(t.category)){t.fromMeal=t.category==='מהתפריט';t.category=info.category}t.shoppingV3=true;changed=true}if(t.art!==info.art){t.art=info.art;changed=true}}if(!data.artV3){data.artV3=true;changed=true}if(changed)save()}
